begin
 select id into strict v_subject from public.subjects where code='informatika';
 for r in select * from jsonb_to_recordset($items$[{"n":301,"construct":"PM.MET.01","stem":"Informatika darsida o‘quvchi ikki algoritmni faqat nomi bilan esladi. Maqsad algoritmlarni solishtirib tanlash bo‘lsa, o‘qituvchi keyin nima qildirishi kerak?","options":["Algoritmlar nomini ko‘proq yodlatish","Vaqtni o‘lchash va kirish-chiqish misollariga tayanib yechimni asoslatish","Masalani o‘qituvchining o‘zi ishlab berishi","Sinovni yakunlash"],"answer":1,"explanation":"Tanlov maqsadiga erishish uchun o‘quvchi algoritmlarni bir xil test va mezon bilan solishtirishi kerak.","cognitive":"mulohaza","difficulty":4},{"n":302,"construct":"PM.MET.01","stem":"Ma’lumotlar bazasi mavzusida o‘quv maqsadi ‘so‘rov yordamida natijani filtrlash’ bo‘lsa, qaysi baholash dalili eng mos?","options":["SQL kalit so‘zlari ro‘yxatini yoddan aytish","Faqat bazaning rangini tanlash","Berilgan shartga mos SQL so‘rovini tuzib, natijasini tekshirish","O‘qituvchi bayonini yozib olish"],"answer":2,"explanation":"Amaliy kompetensiya real so‘rov va uning tekshiriladigan natijasi orqali baholanadi.","cognitive":"qollash","difficulty":3},{"n":303,"construct":"PM.MET.01","stem":"Kompyuter xonasida qurilma yetishmaydi: har ikkita o‘quvchiga bitta kompyuter. Metodik tizimning qaysi moslashuvi maqsadni saqlaydi?","options":["Nazariy va amaliy rollarni navbat bilan almashadigan juftlik ishlari","Barcha amaliy natijalarni baholamaslik","Faqat kuchli o‘quvchilarga kompyuter berish","Amaliy mashqni imtihongacha bekor qilish"],"answer":0,"explanation":"Tashkiliy shakl resursga moslashadi, lekin har bir o‘quvchining amaliy ishtiroki saqlanadi.","cognitive":"qollash","difficulty":3},{"n":304,"construct":"PM.MET.01","stem":"Algoritmlash mashg‘ulotida ‘nima uchun, nima, qanday?’ savollaridan qaysi biri metod va vositani tanlashni anglatadi?","options":["Qanday tushuncha o‘rganiladi?","Qanday kompetensiya zarur?","Nima uchun kerak?","O‘quvchi qaysi faoliyat va vositalar yordamida natijaga erishadi?"],"answer":3,"explanation":"Metodik tizimdagi ‘qanday?’ savoli metodlar, tashkiliy shakllar va vositalarni belgilaydi.","cognitive":"bilish","difficulty":2},{"n":305,"construct":"PM.MET.01","stem":"O‘qituvchi Python sikllarini o‘rgatishda faqat kod namoyish qildi. O‘quvchilar mustaqil sikl tuza olmadi. Bu nimani ko‘rsatadi?","options":["Barcha o‘quvchi kodlashga qobiliyatsiz","Namoyish metodini mustaqil qo‘llash va diagnostika bilan to‘ldirish zarurligini","Koddan butunlay voz kechish kerakligini","Hech qanday pedagogik xulosa qilish mumkin emasligini"],"answer":1,"explanation":"Maqsad mustaqil kod yozish bo‘lsa, mashq va qayta aloqa namoyishning o‘rnini qisman to‘ldiradi.","cognitive":"mulohaza","difficulty":4},{"n":306,"construct":"PM.MET.01","stem":"Tarmoq xavfsizligi bo‘yicha dars maqsadi xavfni aniqlash. Qaysi faoliyat maqsadga ko‘proq mos?","options":["Xavfsizlik so‘zini o‘n marta ko‘chirish","Tarmoq kabellarining rangini tanlash","Qurilmadagi xavfli sozlamalar vaziyatini tahlil qilib, oqibatini asoslash","Faqat provayder logotipini eslab qolish"],"answer":2,"explanation":"Xavfni aniqlash kompetensiyasi vaziyatdagi tahdid belgilarini tahlil qilishga asoslanadi.","cognitive":"qollash","difficulty":3},{"n":307,"construct":"PM.MET.02","stem":"O‘qituvchi kod tuzilishini kichik bosqichlarda ko‘rsatib, har bosqichdan keyin o‘quvchiga davom ettirishni topshirdi. Bu qanday metodik yordam?","options":["Bosqichli tayanch va asta-sekin mustaqillashtirish","Javobni to‘liq aytib berish","Natijani baholashni bekor qilish","Masalani mavzudan uzib tashlash"],"answer":0,"explanation":"Bosqichli yordam tayanch namunadan mustaqil yechimga izchil o‘tishni ta’minlaydi.","cognitive":"qollash","difficulty":3},{"n":308,"construct":"PM.MET.02","stem":"Scratch dasturida o‘quvchilar harakat va shart bloklarini aralashtirib yubordi. Qaysi ish tushunchalar orasidagi farqni ko‘rsatadi?","options":["Bloklar nomini daftar chetiga ko‘chirish","Faqat dastur oynasini kattalashtirish","Bir xil kodni rasmga aylantirish","Kirish shartlari farqli ikkita blok skriptini ishga tushirib, natijani solishtirish"],"answer":3,"explanation":"Shartni o‘zgartirib tajriba qilish bloklarning funksional farqini namoyon etadi.","cognitive":"qollash","difficulty":3},{"n":309,"construct":"PM.MET.02","stem":"‘Ma’lumotlar turlari’ darsida o‘quvchilar ekspert guruhlarda son, matn va mantiqiy tur misollarini o‘rgandi. Asl guruhga qaytgach nima qilishi kerak?","options":["Faqat o‘z ekspert guruhidagi javobni yashirish","Har kim o‘z turi bo‘yicha boshqalarga tushuntirib, umumiy dastur misolida birlashtirish","Faqat o‘qituvchining yakuniy monologini tinglash","Boshqa turlar haqidagi bilimlarni tekshirmaslik"],"answer":1,"explanation":"Ajurli arra usulida ekspert ma’lumotni qaytib o‘rgatadi va umumiy bilim tiklanadi.","cognitive":"qollash","difficulty":3},{"n":310,"construct":"PM.MET.02","stem":"Algoritmning blok-sxemasi va psevdokodi orasidagi farqni anglatish uchun qaysi vosita-metod uyg‘unligi asosli?","options":["Faqat manbalar ro‘yxatini o‘qish","Ustozning tayyor xulosasini ko‘chirish","Bir vazifaning ikki ifodasini taqqoslab, qadamlar mosligini tekshirish","Shakllarning faqat rangini baholash"],"answer":2,"explanation":"Bir xil algoritmning turli tasvirlari qadamlar bo‘yicha solishtirilganda model va ifoda farqlanadi.","cognitive":"mulohaza","difficulty":4},{"n":311,"construct":"PM.MET.02","stem":"Internetdagi ma’lumot ishonchliligini o‘rganishda keys-stadi qaysi ish bilan amalga oshadi?","options":["Bitta xabarni muallif, sana va dalillar bo‘yicha tekshirib, ishonchlilik hukmini asoslash","Sarlavhani tekshirmay ko‘chirib olish","Birgina emoji asosida xulosa qilish","Faqat veb-sahifa rangini tanlash"],"answer":0,"explanation":"Keys-stadi real axborot holatiga doir dalil, alternativ va xulosani baholashni nazarda tutadi.","cognitive":"qollash","difficulty":3},{"n":312,"construct":"PM.MET.02","stem":"O‘qituvchi ‘bugun for siklini tushundikmi?’ deb umumiy so‘radi. Metodik jihatdan yaxshiroq diagnostika qaysi?","options":["Barcha o‘quvchi qo‘l ko‘tarsa kifoya","Siklni tushuntirishni umuman to‘xtatish","Siklni yoddan bir marta aytish","Ikki qiymat uchun sikl bajarilish jadvalini har bir o‘quvchi alohida tuzishi"],"answer":3,"explanation":"Har bir o‘quvchining kuzatiladigan ishi yoppasiga berilgan ‘tushundikmi?’ savolidan aniqroq dalil beradi.","cognitive":"qollash","difficulty":3},{"n":313,"construct":"PM.MET.03","stem":"O‘quvchi kodi normal kirishda ishlaydi, lekin bo‘sh ro‘yxatda xato beradi. To‘g‘ri metodik qaror qaysi?","options":["Faqat normal kirishni qayta sinash","Chegaraviy holatni ajratib, algoritm shartlarini tekshirtirish","Xatoni atayin yashirish","Kodning rangli qismini o‘zgartirish"],"answer":1,"explanation":"Chegaraviy holat asosida diagnostika qilish muammo sababini aniqlashga o‘rgatadi.","cognitive":"mulohaza","difficulty":4},{"n":314,"construct":"PM.MET.03","stem":"Dastur natijasi noto‘g‘ri chiqqanda o‘quvchi bir vaqtning o‘zida besh qatorni o‘zgartirdi. O‘qituvchi qanday maslahat beradi?","options":["Shu usulni doimiy qo‘llash","Kodga aloqador bo‘lmagan fayllarni o‘chirish","Bir o‘zgarishni amalga oshirib, har safar qayta testlash va kuzatishni yozish","Har qanday testdan voz kechish"],"answer":2,"explanation":"Bir o‘zgaruvchi yoki qadamni nazorat ostida tekshirish xato sababini ajratishga yordam beradi.","cognitive":"qollash","difficulty":3},{"n":315,"construct":"PM.MET.03","stem":"Matnli faylni qayta ishlash vazifasida o‘quvchi dastlab noto‘g‘ri kodlashni tanladi. Eng yaxshi qayta aloqa qaysi?","options":["Fayldagi belgilar buzilishining sababini kodlash turidan izlatish va tanlovni tekshirtirish","Dasturini hech qanday izohsiz rad etish","Kodlash nima ekanini so‘ramaslik","Faylni o‘qimasdan baholash"],"answer":0,"explanation":"Tashxisga asoslangan maslahat o‘quvchini kodlash va natija o‘rtasidagi bog‘liqlikni anglashga olib keladi.","cognitive":"mulohaza","difficulty":4},{"n":316,"construct":"PM.MET.03","stem":"Qiyin algoritmik masalada ayrim o‘quvchilar boshqalardan orqada qoldi. Maqsadni pasaytirmasdan qanday ko‘mak mumkin?","options":["Orqada qolganlarni boshqa mavzuga yuborish","Hamma uchun vaqtni aynan teng qilmaslik uchun bahoni bekor qilish","Ularning kodini tayyor nusxadan almashtirish","Kiruvchi ma’lumotning kichik namunalaridan boshlatib, tayanch savollar bilan murakkablikni oshirish"],"answer":3,"explanation":"Bosqichli individual yordam va kichik testlar umumiy o‘quv maqsadiga olib boradi.","cognitive":"qollash","difficulty":3},{"n":317,"construct":"PM.MET.03","stem":"O‘quvchi SQL so‘rovi kutilmagan qatorlarni qaytardi. O‘qituvchi eng avval qaysi diagnostik savolni beradi?","options":["Jadval fonining rangi qaysi?","WHERE sharti qaysi yozuvlarni tanlayotganini namunaviy qatorlarda tekshirib ko‘rdingmi?","Sinfga qanday qo‘shiq yoqadi?","Kompyuter qachon xarid qilingan?"],"answer":1,"explanation":"So‘rovdagi filtr shartini real satrlarga tatbiq qilish mantiqiy xatoni aniqlashda asosiy qadamdir.","cognitive":"qollash","difficulty":3},{"n":318,"construct":"PM.MET.03","stem":"Python dasturi 'IndexError' berdi. O‘qituvchi kodni o‘zi tuzatmay, qanday savol bilan o‘quvchini o‘ylantiradi?","options":["Bugun sinfda nechta parta bor?","Dasturni to‘liq o‘chirib qayta yozdingmi?","Ro‘yxat uzunligi bilan murojaat qilayotgan indeks qanday bog‘langan?","Kod satrini tushunmay ko‘chirganmiding?"],"answer":2,"explanation":"Indeks va uzunlikning chegarasi tushuntirilsa, o‘quvchi mustaqil xato tuzatishni o‘rganadi.","cognitive":"qollash","difficulty":3},{"n":319,"construct":"KS.02","stem":"Jamoa ishida ikki o‘quvchi vazifani bajardi, qolganlari tomoshabin bo‘ldi. Ta’lim samaradorligi nuqtayi nazaridan nima qilish kerak?","options":["Har biriga tekshiriladigan kichik rol va navbatli faoliyat ajratish","Ishni faqat faol ikki o‘quvchiga qoldirish","Jamoa ishlarini butunlay taqiqlash","Barcha natijalarni bilmasdan tenglashtirish"],"answer":0,"explanation":"Faol ishtirok har bir o‘quvchining tekshiriladigan ishini tashkil etish bilan ta’minlanadi.","cognitive":"qollash","difficulty":3},{"n":320,"construct":"KS.02","stem":"Yangi mavzudagi amaliy topshiriqlar uchun vaqt yetmay qoldi. Keyingi rejalashda qaysi qaror asosli?","options":["Vaqt hisobini umuman ishlatmaslik","O‘quvchilarga qayta aloqa bermaslik","Dars bosqichlari vaqtini, maqsadga mos mashq va yakuniy diagnostikani muvozanatlashtirish","Mashg‘ulotni faqat diktantga aylantirish"],"answer":2,"explanation":"Ta’lim samaradorligi vaqtni maqsad, mashq va natija tekshiruviga muvofiq taqsimlashni talab qiladi.","cognitive":"mulohaza","difficulty":4},{"n":321,"construct":"KS.04","stem":"Texnologik loyiha guruhida o‘quvchilar boshqalarning mehnat natijasidan ruxsatsiz foydalanmoqda. Tarbiyaviy maqsadga mos chorani tanlang.","options":["Vaziyatni e’tiborsiz qoldirish","Mualliflik, o‘zaro hurmat va mehnatga mas’uliyatni muhokama qilib, kelishuv ishlab chiqish","Barcha guruhni uzoq muddat chetlatish","Faqat dizaynni bezash"],"answer":1,"explanation":"Tarbiyaviy faoliyatda halollik, hamkorlik va boshqalarning mehnatini qadrlash mustahkamlanadi.","cognitive":"qollash","difficulty":3},{"n":322,"construct":"KS.04","stem":"Sinf loyihasida o‘quvchilar bir-birining fikrini eshitmayapti. O‘qituvchi tarbiyaviy natijani nimadan biladi?","options":["Faqat taqdimotdagi slaydlar sonidan","Loyihaning fayl hajmidan","Faqat darsga kelganlar sonidan","Guruh a’zolari hurmatli munozara qilib, vazifani kelishib bajarayotganidan"],"answer":3,"explanation":"Tarbiyaviy natija muomala, hamkorlik va mas’uliyatli xatti-harakatlarda kuzatiladi.","cognitive":"mulohaza","difficulty":4},{"n":323,"construct":"KS.06","stem":"O‘qituvchi yangi metodni o‘rgandi. Uning kasbiy rivojlanganini qaysi dalil yaxshiroq ko‘rsatadi?","options":["Seminar nomini yodda saqlash","Metod nomini reja boshiga yozish","Darsda metodni sinab, o‘quvchi natijasini tahlil qilish va amaliyotini tuzatish","Sinf jihozlarini o‘zgartirish"],"answer":2,"explanation":"Kasbiy o‘sish yangi bilimni amaliyotda tatbiq etish va dalil bilan refleksiya qilishda ko‘rinadi.","cognitive":"qollash","difficulty":3},{"n":324,"construct":"KS.06","stem":"O‘qituvchi o‘z darsining video yozuvini faqat shaxsiy tahlil uchun ko‘rmoqchi. Qanday professional ehtiyot chorasi zarur?","options":["Ruxsat va maxfiylik talablariga rioya qilib, yozuvdan maqsadli foydalanish","Videoni barcha ochiq guruhlarga tarqatish","O‘quvchilarni roziligisiz reklamada ko‘rsatish","Shaxsiy ma’lumotlarni sinfda e’lon qilish"],"answer":0,"explanation":"Refleksiya jarayonida ham o‘quvchilar huquqi va shaxsiy ma’lumotlar xavfsizligi saqlanadi.","cognitive":"mulohaza","difficulty":4},{"n":325,"construct":"KS.07","stem":"Yangi raqamli platformani joriy etishda hamkasblar o‘rtasida qarama-qarshi fikr chiqdi. Hamkorlikni qanday yo‘l bilan boshlash maqsadga muvofiq?","options":["Faqat bitta fikrni majburan qabul qildirish","Bahsdan qochib, barcha ishni to‘xtatish","Darslar haqida shaxsiy tanbeh berish","Aniq o‘quv maqsadi, cheklov va sinov mezonlarini birga kelishib olish"],"answer":3,"explanation":"Kasbiy hamkorlik umumiy maqsad va dalilli qaror uchun mas’uliyatni taqsimlashni talab qiladi.","cognitive":"mulohaza","difficulty":4},{"n":326,"construct":"KS.07","stem":"Ota-onaga farzandining o‘rganishdagi qiyinchiligini aytishda qaysi muloqot eng asosli?","options":["Bolaning xatolarini boshqa o‘quvchilar bilan solishtirib uyaltirish","Aniq kuzatuv dalili, kuchli tomon va keyingi yordam rejasini hamkorlikda belgilash","Hech qanday misolsiz tanbeh berish","Faqat boshqalarning shaxsiy ma’lumotlarini oshkor qilish"],"answer":1,"explanation":"Dalilga tayangan, hurmatli va aniq kelishuvli muloqot bola rivojini qo‘llaydi.","cognitive":"qollash","difficulty":3},{"n":327,"construct":"PM.GEN.02","stem":"Ko‘rsatmalilik tamoyilini raqamli vositada qo‘llash uchun qaysi harakat ilmiy jihatdan asosli?","options":["Har mavzuni faqat bezakli animatsiya bilan boshlash","O‘quvchi tajribasini hisobga olmaslik","Sxema yoki simulyatsiyani mavzuning muhim munosabatini tushuntirishga xizmat qildirish","Dars mazmunini e’tiborsiz qoldirib rang tanlash"],"answer":2,"explanation":"Ko‘rsatma o‘rganilayotgan munosabatni ochishi kerak; bezakning o‘zi didaktik maqsad emas.","cognitive":"qollash","difficulty":3},{"n":328,"construct":"PM.GEN.04","stem":"O‘quvchilarni qiyin topshiriqqa tayyorlashda dastlabki diagnostika nima uchun kerak?","options":["Oldingi bilimdagi bo‘shliqlarni aniqlab, keyingi mashq va ko‘makni belgilash","Faqat umumiy baholar sonini ko‘paytirish","O‘quvchini xatosi uchun jazolash","Dars maqsadidan voz kechish"],"answer":0,"explanation":"Boshlang‘ich diagnostika keyingi dars qarorini avvalgi tayyorgarlikka moslashtirishga yordam beradi.","cognitive":"qollash","difficulty":3},{"n":329,"construct":"PM.GEN.06","stem":"O‘quvchi javobi noaniq bo‘lganda muallim savolni salbiy ohangda qaytarmadi, aniqlashtiruvchi misol so‘radi. Bu qanday muloqot namunasidir?","options":["Avtoritar muomala bilan bo‘ysundirish","Pedagogik takt va qo‘llab-quvvatlovchi qayta aloqa","Natijalarni yashirish","Muammo haqida eshitmaslik"],"answer":1,"explanation":"Pedagogik takt tanqidni kamsitmasdan, o‘quvchi fikrini aniqlashtirishga yordam beradi.","cognitive":"qollash","difficulty":3},{"n":330,"construct":"PM.GEN.08","stem":"Sinfga qaysi metodni berishni tanlashda birinchi mezon sifatida nima olinishi kerak?","options":["Qaysi metod nomi hozir urfda ekanini","O‘qituvchi ilgari ishlatmagan metodni","Dars slaydi rangini","O‘quv natijasi, vazifa xususiyati va o‘quvchilarning tayyorgarligini"],"answer":3,"explanation":"O‘qitish metodi maqsad, mazmun va ehtiyoj bilan mos bo‘lsa didaktik natija oshadi.","cognitive":"mulohaza","difficulty":4}]$items$::jsonb)
 as t(n int,construct text,stem text,options jsonb,answer int,explanation text,cognitive text,difficulty int)
 loop
   select c.id,l.id into v_construct,v_lesson from public.constructs c
   join public.lesson_constructs lc on lc.construct_id=c.id
   join public.lessons l on l.id=lc.lesson_id
   where c.code=r.construct and c.is_active and l.status='published'::public.content_status
     and l.slug !~ '^m(14|15|16)-[0-9]+$'
   order by l.order_idx,l.id limit 1;
   if v_construct is null or v_lesson is null then raise exception 'no canonical lesson for %',r.construct;end if;
   v_qid:=('79300000-0000-4000-8000-'||lpad(r.n::text,12,'0'))::uuid;
   insert into public.questions (id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,source_reference,source_lesson_id)
   values (v_qid,v_subject,v_construct,
     case when r.construct like 'KS.%' then 'KS' when r.construct like 'PM.GEN.%' then 'PM.GEN' else 'PM.MET' end,
     'Y1'::public.question_format,r.cognitive::public.cognitive_level,r.difficulty,r.stem,
     'published'::public.content_status,'authored:pedguli-topic-audit:v4:'||r.construct||':'||r.n,v_lesson)
   on conflict (id) do nothing;
   for i in 0..3 loop
     v_oid:=('79310000-0000-4000-8000-'||lpad((r.n*10+i)::text,12,'0'))::uuid;
     insert into public.question_options(id,question_id,side,order_idx,content_md)
     values(v_oid,v_qid,'a',i+1,r.options->>i) on conflict(id) do nothing;
   end loop;
   v_oid:=('79310000-0000-4000-8000-'||lpad((r.n*10+r.answer)::text,12,'0'))::uuid;
   insert into public.question_keys(question_id,payload,explanation_md)
   values(v_qid,jsonb_build_object('correct_option_id',v_oid),r.explanation)
   on conflict(question_id) do nothing;
 end loop;
end
$bank_v4$;
commit;